from __future__ import annotations

import base64
import re
import subprocess
import zlib
from pathlib import Path


def git_show(ref: str, path: str) -> bytes:
    return subprocess.check_output(["git", "show", f"{ref}:{path}"])


def copy_file(ref: str, path: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(git_show(ref, path))


platform_ref = "1143f6e3eb355e6de1e434083ff2c974efd78708"
for path in (
    "docs/guard/secrets-platform-hardening.md",
    "scripts/ci/run_guard_secrets_platform_smoke_v2.py",
    "src/codex_plugin_scanner/guard/secrets/cli.py",
    "tests/test_guard_secret_git_subprocess_hardening.py",
    "tests/test_guard_secret_hook_configuration_hardening.py",
    "tests/test_guard_secret_input_coverage_hardening.py",
    "tests/test_guard_secret_platform_hardening.py",
):
    copy_file(platform_ref, path)

copy_file(
    "5f5befcf2aa847d2813d40e8bf47f4ce4f5a95d2",
    "tests/test_guard_secret_git_process_security.py",
)
copy_file(
    "1de19656af287ced5a8cac17b2986053c125afca",
    "tests/test_guard_secret_git_repository_edges.py",
)
copy_file(
    "1de19656af287ced5a8cac17b2986053c125afca",
    "scripts/ci/run_guard_secrets_pipx_smoke.py",
)

workflow = git_show(
    "5f5befcf2aa847d2813d40e8bf47f4ce4f5a95d2",
    ".github/workflows/secrets-git-process-bootstrap.yml",
).decode("utf-8")
match = re.search(
    r"cat > src/codex_plugin_scanner/guard/secrets/git_safe\.py <<'PY'\n(.*?)\n          PY",
    workflow,
    flags=re.S,
)
if match is None:
    raise SystemExit("reviewed git_safe source block not found")
lines = match.group(1).splitlines()
first = next((line for line in lines if line.strip()), "")
indent = len(first) - len(first.lstrip())
prefix = " " * indent
git_safe = "\n".join(line[indent:] if line.startswith(prefix) else line for line in lines)
Path("src/codex_plugin_scanner/guard/secrets/git_safe.py").write_text(
    git_safe.rstrip() + "\n",
    encoding="utf-8",
)

compressed_files = {"src/codex_plugin_scanner/guard/secrets/git_subprocess.py": "", "src/codex_plugin_scanner/guard/secrets/precommit.py": "", "src/codex_plugin_scanner/guard/secrets/secret_repository_scanner.py": "", "src/codex_plugin_scanner/guard/secrets/secret_staged_scanner.py": "", "src/codex_plugin_scanner/guard/secrets/setup_diagnostics.py": "", "src/codex_plugin_scanner/guard/secrets/git_subprocess.py": ""}
for path, payload in compressed_files.items():
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(zlib.decompress(base64.b64decode(payload)))

platform_test = Path("tests/test_guard_secret_platform_hardening.py")
text = platform_test.read_text(encoding="utf-8")
text = text.replace(
    '    assert "command -v hol-guard" in managed\n'
    '    assert "scan --staged --fail-on-findings" in managed\n',
    '    assert "command -v hol-guard" not in managed\n'
    '    assert "exec hol-guard" not in managed\n'
    '    assert "scan --staged --fail-on-findings" in managed\n'
    '    assert "pinned Guard executable is unavailable" in managed\n',
)
text = text.replace(
    '    assert "could not find the hol-guard executable" in result.stderr\n',
    '    assert "git_staged_enumeration_failed" in result.stderr\n'
    '    assert "pinned Guard executable is unavailable" not in result.stderr\n',
)
text = text.replace(
    '    assert not any(key.startswith("GIT_CONFIG_") for key in environment)\n',
    '    assert environment["GIT_CONFIG_GLOBAL"] == os.devnull\n'
    '    assert environment["GIT_CONFIG_NOSYSTEM"] == "1"\n'
    '    assert environment["GIT_CONFIG_SYSTEM"] == os.devnull\n',
)
platform_test.write_text(text, encoding="utf-8")

docs = Path("docs/guard/secrets-platform-hardening.md")
if docs.exists():
    body = docs.read_text(encoding="utf-8")
    addition = (
        "\n## Fail-honest repository evidence\n\n"
        "- Git LFS pointers are partial until referenced contents are materialized and scanned.\n"
        "- Submodules are separate repositories and require separate scans.\n"
        "- Shallow clones, promisor partial clones, grafts, replace refs, alternate object stores, sparse checkouts, and bare repositories are surfaced explicitly.\n"
        "- Managed pre-commit hooks pin the installed Guard identity, repair stale managed hooks, and refuse linked worktrees or custom hook managers.\n"
    )
    if "## Fail-honest repository evidence" not in body:
        docs.write_text(body.rstrip() + addition + "\n", encoding="utf-8")
